// The chain brands' signboard pictures: each brand's real logo, downsampled to 32×32 from the
// reference in tools/bake/logo-refs/<brand>.png by tools/bake/brand_logos.mjs (which re-creates this
// file). One RGBA picture a brand, the board colour already behind it; the atlas (below) is sampled
// whole by shaders-brands.js. The order is pixelcity/brands.py's TABLE — index.json's brandMarks
// carries it and the page checks the two against each other at boot.
export const BRAND_LOGOS = [
  { brand: 'mcd', board: 'brand_red', rgba: '' },
  { brand: 'kfc', board: 'brand_red', rgba: '' },
  { brand: 'pizza_hut', board: 'brand_red', rgba: '' },
  { brand: 'burger_king', board: 'brand_orange', rgba: '' },
  { brand: 'tastien', board: 'brand_gold', rgba: '' },
  { brand: 'starbucks', board: 'brand_green', rgba: '' },
  { brand: 'luckin', board: 'brand_navy', rgba: '' },
  { brand: 'cotti', board: 'brand_red', rgba: '' },
  { brand: 'heytea', board: 'panel_white', rgba: '' },
  { brand: 'nayuki', board: 'panel_white', rgba: '' },
  { brand: 'mixue', board: 'brand_red', rgba: '' },
  { brand: 'chabaidao', board: 'brand_orange', rgba: '' },
  { brand: 'chagee', board: 'glass_teal', rgba: '' },
  { brand: 'haidilao', board: 'brand_red', rgba: '' },
  { brand: 'familymart', board: 'brand_blue', rgba: '' },
  { brand: 'seven_eleven', board: 'brand_orange', rgba: '' },
  { brand: 'lawson', board: 'brand_blue', rgba: '' },
  { brand: 'hema', board: 'brand_blue', rgba: '' },
  { brand: 'sam', board: 'glass_teal', rgba: '' },
  { brand: 'walmart', board: 'brand_blue', rgba: '' },
  { brand: 'rtmart', board: 'brand_orange', rgba: '' },
  { brand: 'uniqlo', board: 'brand_red', rgba: '' },
  { brand: 'miniso', board: 'brand_red', rgba: '' },
];

// 每个品牌一张 32×32 的纹理，按 BRAND_LOGOS 的顺序（=品牌的编号）排好；绘制时按编号取用。
export function brandTextures(gl) {
  const size = 32;
  const textures = BRAND_LOGOS.map((logo, i) => {
    const bytes = Uint8Array.from(atob(logo.rgba), c => c.charCodeAt(0));
    if (bytes.length !== size * size * 4) throw new Error(`${logo.brand} 的招牌画不是 ${size}×${size}`);
    const texture = gl.createTexture();
    gl.bindTexture(gl.TEXTURE_2D, texture);
    gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, size, size, 0, gl.RGBA, gl.UNSIGNED_BYTE, bytes);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.NEAREST);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.NEAREST);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
    return texture;
  });
  return { textures, count: textures.length };
}
